import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class Solution {
    private Solution() {}

    public static final class SortTrace {
        private final int[] sorted;
        private final List<int[]> passes;

        private SortTrace(int[] sorted, List<int[]> passes) {
            this.sorted = sorted.clone();
            this.passes = new ArrayList<int[]>();
            for (int[] pass : passes) {
                this.passes.add(pass.clone());
            }
        }

        public int[] getSorted() {
            return sorted.clone();
        }

        public List<int[]> getPasses() {
            List<int[]> copy = new ArrayList<int[]>();
            for (int[] pass : passes) {
                copy.add(pass.clone());
            }
            return Collections.unmodifiableList(copy);
        }
    }

    public static SortTrace traceDescending(int[] values) {
        if (values == null) {
            throw new IllegalArgumentException("values is null");
        }

        int[] work = values.clone();
        List<int[]> passes = new ArrayList<int[]>();
        if (work.length < 2) {
            return new SortTrace(work, passes);
        }

        int end = work.length - 1;
        while (true) {
            boolean swapped = false;
            for (int i = 0; i < end; i++) {
                if (work[i] < work[i + 1]) {
                    int temporary = work[i];
                    work[i] = work[i + 1];
                    work[i + 1] = temporary;
                    swapped = true;
                }
            }
            passes.add(work.clone());
            if (!swapped) {
                break;
            }
            if (end > 1) {
                end--;
            }
        }

        return new SortTrace(work, passes);
    }
}
